/* eslint-disable */
var jumpToCode = (function init() {
    // Classes of code we would like to highlight in the file view
    var missingCoverageClasses = ['.cbranch-no', '.cstat-no', '.fstat-no'];

    // Elements to highlight in the file listing view
    var fileListingElements = ['td.pct.low'];

    // We don't want to select elements that are direct descendants of another match
    var notSelector = ':not(' + missingCoverageClasses.join('):not(') + ') > '; // becomes `:not(a):not(b) > `

    // Selector that finds elements on the page to which we can jump
    var selector =
        fileListingElements.join(', ') +
        ', ' +
        notSelector +
        missingCoverageClasses.join(', ' + notSelector); // becomes `:not(a):not(b) > a, :not(a):not(b) > b`

    // The NodeList of matching elements
    var missingCoverageElements = document.querySelectorAll(selector);

    var currentIndex;

    function toggleClass(index) {
        missingCoverageElements
            .item(currentIndex)
            .classList.remove('highlighted');
        missingCoverageElements.item(index).classList.add('highlighted');
    }

    function makeCurrent(index) {
        toggleClass(index);
        currentIndex = index;
        missingCoverageElements.item(index).scrollIntoView({
            behavior: 'smooth',
            block: 'center',
            inline: 'center'
        });
    }

    function goToPrevious() {
        var nextIndex = 0;
        if (typeof currentIndex !== 'number' || currentIndex === 0) {
            nextIndex = missingCoverageElements.length - 1;
        } else if (missingCoverageElements.length > 1) {
            nextIndex = currentIndex - 1;
        }

        makeCurrent(nextIndex);
    }

    function goToNext() {
        var nextIndex = 0;

        if (
            typeof currentIndex === 'number' &&
            currentIndex < missingCoverageElements.length - 1
        ) {
            nextIndex = currentIndex + 1;
        }

        makeCurrent(nextIndex);
    }

    return function jump(event) {
        if (
            document.getElementById('fileSearch') === document.activeElement &&
            document.activeElement != null
        ) {
            // if we're currently focused on the search input, we don't want to navigate
            return;
        }

        switch (event.which) {
            case 78: // n
            case 74: // j
                goToNext();
                break;
            case 66: // b
            case 75: // k
            case 80: // p
                goToPrevious();
                break;
        }
    };
})();
window.addEventListener('keydown', jumpToCode);

import { describe, it, expect, vi, beforeEach } from "vitest";
import { GET, POST } from "./route";
import prisma from "@/lib/prisma";
import { getServerSession } from "next-auth";

vi.mock("next-auth", () => ({
  getServerSession: vi.fn(),
}));

vi.mock("@/lib/prisma", () => ({
  default: {
    userProfile: {
      findUnique: vi.fn(),
      upsert: vi.fn(),
    },
    goal: {
      findUnique: vi.fn(),
      upsert: vi.fn(),
    },
    user: {
      update: vi.fn(),
      findUnique: vi.fn(),
    },
  },
}));

describe("Profile API Route", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  describe("GET", () => {
    it("returns 401 if not authenticated", async () => {
      vi.mocked(getServerSession).mockResolvedValue(null);
      const req = new Request("http://localhost/api/profile");
      const res = await GET(req);
      expect(res.status).toBe(401);
    });

    it("returns profile data for authenticated user", async () => {
      const mockSession = { user: { id: "user-1", email: "test@example.com" } };
      vi.mocked(getServerSession).mockResolvedValue(mockSession as unknown);

      const mockProfile = { userId: "user-1", age: 30, gender: "Male" };
      const mockUser = {
        name: "Test User",
        email: "test@example.com",
        phone: null,
        username: null,
      };
      vi.mocked(prisma.userProfile.findUnique).mockResolvedValue(
        mockProfile as unknown,
      ); // eslint-disable-line @typescript-eslint/no-explicit-any
      vi.mocked(prisma.user.findUnique).mockResolvedValue(mockUser as unknown);

      const req = new Request("http://localhost/api/profile");
      const res = await GET(req);
      const data = await res.json();

      expect(res.status).toBe(200);
      expect(data).toEqual({ ...mockProfile, ...mockUser });
      expect(prisma.userProfile.findUnique).toHaveBeenCalledWith({
        where: { userId: "user-1" },
      });
      expect(prisma.user.findUnique).toHaveBeenCalledWith({
        where: { id: "user-1" },
      });
    });

    it("returns goal data when type=goals is requested", async () => {
      const mockUser = { id: "user-1" };
      vi.mocked(getServerSession).mockResolvedValue({ user: mockUser });

      const mockGoal = { userId: "user-1", proteinTarget: 150 };
      vi.mocked(prisma.goal.findUnique).mockResolvedValue(mockGoal as unknown); // eslint-disable-line @typescript-eslint/no-explicit-any

      const req = new Request("http://localhost/api/profile?type=goals");
      const res = await GET(req);
      const data = await res.json();

      expect(res.status).toBe(200);
      expect(data).toEqual(mockGoal);
      expect(prisma.goal.findUnique).toHaveBeenCalledWith({
        where: { userId: "user-1" },
      });
    });
  });

  describe("POST", () => {
    it("returns 401 if not authenticated", async () => {
      vi.mocked(getServerSession).mockResolvedValue(null);
      const req = new Request("http://localhost/api/profile", {
        method: "POST",
        body: JSON.stringify({}),
      });
      const res = await POST(req);
      expect(res.status).toBe(401);
    });

    it("updates profile data", async () => {
      const mockUser = { id: "user-1" };
      vi.mocked(getServerSession).mockResolvedValue({ user: mockUser });

      const updateData = { age: 31, gender: "Male", name: "New Name" };
      vi.mocked(prisma.userProfile.upsert).mockResolvedValue({
        userId: "user-1",
        ...updateData,
      } as unknown); // eslint-disable-line @typescript-eslint/no-explicit-any

      const req = new Request("http://localhost/api/profile", {
        method: "POST",
        body: JSON.stringify(updateData),
      });
      const res = await POST(req);
      await res.json();

      expect(res.status).toBe(200);
      expect(prisma.userProfile.upsert).toHaveBeenCalled();
      expect(prisma.user.update).toHaveBeenCalledWith({
        where: { id: "user-1" },
        data: { name: "New Name" },
      });
    });

    it("updates goal data if goal fields are present", async () => {
      const mockUser = { id: "user-1" };
      vi.mocked(getServerSession).mockResolvedValue({ user: mockUser });

      const goalData = { proteinTarget: 180, kcalTarget: 2500 };
      vi.mocked(prisma.goal.upsert).mockResolvedValue({
        userId: "user-1",
        ...goalData,
      } as unknown); // eslint-disable-line @typescript-eslint/no-explicit-any

      const req = new Request("http://localhost/api/profile", {
        method: "POST",
        body: JSON.stringify(goalData),
      });
      const res = await POST(req);
      await res.json();

      expect(res.status).toBe(200);
      expect(prisma.goal.upsert).toHaveBeenCalled();
    });

    it("returns 400 for invalid profile data", async () => {
      const mockUser = { id: "user-1" };
      vi.mocked(getServerSession).mockResolvedValue({ user: mockUser });

      const invalidData = { age: "invalid" }; // age should be number (forced by schema)
      const req = new Request("http://localhost/api/profile", {
        method: "POST",
        body: JSON.stringify(invalidData),
      });
      const res = await POST(req);
      const data = await res.json();

      expect(res.status).toBe(400);
      expect(data).toHaveProperty("error");
    });

    it("returns 400 for invalid goal data in POST", async () => {
      vi.mocked(getServerSession).mockResolvedValue({ user: { id: "user-1" } });
      const res = await POST(
        new Request("http://localhost/api/profile", {
          method: "POST",
          body: JSON.stringify({ proteinTarget: -10 }),
        }),
      );
      expect(res.status).toBe(400);
    });

    it("returns 500 if database fails on GET", async () => {
      vi.mocked(getServerSession).mockResolvedValue({ user: { id: "user-1" } });
      vi.mocked(prisma.userProfile.findUnique).mockRejectedValueOnce(
        new Error("DB Error"),
      );
      const res = await GET(new Request("http://localhost/api/profile"));
      expect(res.status).toBe(500);
    });

    it("returns 500 if database fails on POST", async () => {
      vi.mocked(getServerSession).mockResolvedValue({ user: { id: "user-1" } });
      vi.mocked(prisma.userProfile.upsert).mockRejectedValueOnce(
        new Error("DB Error"),
      );
      const res = await POST(
        new Request("http://localhost/api/profile", {
          method: "POST",
          body: JSON.stringify({ age: 30 }),
        }),
      );
      expect(res.status).toBe(500);
    });
  });
});

import {
  render,
  screen,
  fireEvent,
  waitFor,
  cleanup,
  act,
} from "@testing-library/react";
import { describe, it, expect, vi, beforeEach, afterEach } from "vitest";
import Home from "./page";
import { useSession } from "next-auth/react";
import { useSearchParams, useRouter } from "next/navigation";
import * as clientApi from "@/lib/client-api";
import React from "react";

// STUBS
if (typeof globalThis !== "undefined") {
  (globalThis as unknown).HTMLElement.prototype.scrollIntoView = vi.fn(); // eslint-disable-line @typescript-eslint/no-explicit-any
  (globalThis as unknown).scrollTo = vi.fn(); // eslint-disable-line @typescript-eslint/no-explicit-any
}

// MOCKS
vi.mock("next-auth/react", () => ({
  useSession: vi.fn(),
  signIn: vi.fn(),
  signOut: vi.fn(),
}));

vi.mock("next/navigation", () => ({
  useRouter: vi.fn(),
  useSearchParams: vi.fn(),
  usePathname: vi.fn(() => "/"),
}));

vi.mock("framer-motion", () => ({
  motion: {
    div: ({ children, ...props }: unknown) => <div {...props}>{children}</div>, // eslint-disable-line @typescript-eslint/no-explicit-any
    button: ({ children, ...props }: unknown) => (
      <button {...props}>{children}</button>
    ), // eslint-disable-line @typescript-eslint/no-explicit-any
  },
  AnimatePresence: ({ children }: unknown) => <>{children}</>, // eslint-disable-line @typescript-eslint/no-explicit-any
}));

// Mock sub-components to isolate Dashboard logic
vi.mock("@/components/Navbar", () => ({
  default: (
    { activeTab, setActiveTab, toggleTheme }: unknown, // eslint-disable-line @typescript-eslint/no-explicit-any
  ) => (
    <nav data-testid="navbar">
      <button onClick={() => setActiveTab("profile")}>Profile Link</button>
      <button aria-label="Toggle theme" onClick={toggleTheme}>
        Theme Toggle
      </button>
      <div data-active-tab={activeTab}>Navbar</div>
    </nav>
  ),
}));

vi.mock("@/components/Sidebar", () => ({
  default: () => <div data-testid="sidebar" />,
}));
vi.mock("@/components/Chat", () => ({
  default: () => <div data-testid="chat-component" />,
}));
vi.mock("@/components/Tabs/LogTab", () => ({
  default: () => <div data-testid="log-tab" />,
}));
vi.mock("@/components/Tabs/HistoryTab", () => ({
  default: () => <div data-testid="history-tab" />,
}));
vi.mock("@/components/Tabs/BodyTab", () => ({
  default: (
    { handleSaveMeasurements }: unknown, // eslint-disable-line @typescript-eslint/no-explicit-any
  ) => (
    <div data-testid="body-tab">
      <button onClick={handleSaveMeasurements}>Save Measurements</button>
    </div>
  ),
}));
vi.mock("@/components/Tabs/ProfileTab", () => ({
  default: (
    { handleSaveProfile, handleSaveGoals }: unknown, // eslint-disable-line @typescript-eslint/no-explicit-any
  ) => (
    <div data-testid="profile-tab">
      <button onClick={handleSaveProfile}>Save Profile</button>
      <button onClick={handleSaveGoals}>Save Goals</button>
    </div>
  ),
}));

vi.mock("@/lib/client-api", () => ({
  getClientErrorMessage: vi.fn((err) =>
    err instanceof Error ? err.message : String(err),
  ),
  requestJson: vi.fn(() => Promise.resolve([])),
}));

describe("Home (Dashboard) Orchestration", () => {
  const mockRouter = { push: vi.fn(), refresh: vi.fn() };
  let mockSearchParams = new URLSearchParams();

  beforeEach(() => {
    vi.clearAllMocks();
    mockSearchParams = new URLSearchParams();

    vi.stubGlobal("location", { href: "http://localhost/" });
    vi.stubGlobal(
      "fetch",
      vi.fn(() =>
        Promise.resolve({ ok: true, json: () => Promise.resolve([]) }),
      ),
    );

    (useSession as unknown).mockReturnValue({
      data: { user: { id: "test-user" } },
      status: "authenticated",
    }); // eslint-disable-line @typescript-eslint/no-explicit-any
    (useRouter as unknown).mockReturnValue(mockRouter); // eslint-disable-line @typescript-eslint/no-explicit-any
    (useSearchParams as unknown).mockReturnValue(mockSearchParams); // eslint-disable-line @typescript-eslint/no-explicit-any

    // Dashboard data mock
    (clientApi.requestJson as unknown).mockImplementation((url: string) => {
      // eslint-disable-line @typescript-eslint/no-explicit-any
      if (url === "/api/logs")
        return Promise.resolve({ food: [], workouts: [], sleep: [] });
      if (url === "/api/profile") return Promise.resolve({ age: 30 });
      if (url === "/api/goals") return Promise.resolve({ proteinTarget: 150 });
      return Promise.resolve({});
    });
  });

  afterEach(() => {
    cleanup();
    vi.unstubAllGlobals();
  });

  it("renders navbar and sidebar", async () => {
    render(<Home />);
    await waitFor(() => {
      expect(screen.getByTestId("navbar")).toBeDefined();
    });
  });

  it("defaults to chat tab when no tab is specified", async () => {
    render(<Home />);
    await waitFor(() => {
      expect(screen.getByTestId("chat-component")).toBeDefined();
    });
  });

  it("renders specific tab from search params", async () => {
    (useSearchParams as unknown).mockReturnValue(new URLSearchParams("tab=body")); // eslint-disable-line @typescript-eslint/no-explicit-any
    render(<Home />);
    await waitFor(() => {
      expect(screen.getByTestId("body-tab")).toBeDefined();
    });
  });

  it("toggles theme state", async () => {
    render(<Home />);
    const themeBtn = await screen.findByLabelText(/Toggle theme/i);

    fireEvent.click(themeBtn);
    expect(document.documentElement.dataset.theme).toBe("dark");

    fireEvent.click(themeBtn);
    expect(document.documentElement.dataset.theme).toBe("light");
  });

  it("handles tab switching through navbar", async () => {
    render(<Home />);
    const profileBtn = await screen.findByText(/Profile Link/i);
    fireEvent.click(profileBtn);

    expect(mockRouter.push).toHaveBeenCalledWith(
      "/?tab=profile",
      expect.anything(),
    );
  });

  it("processes measurement saves with notifications", async () => {
    (useSearchParams as unknown).mockReturnValue(new URLSearchParams("tab=body")); // eslint-disable-line @typescript-eslint/no-explicit-any
    render(<Home />);

    const saveBtn = await screen.findByText(/Save Measurements/i);
    (clientApi.requestJson as unknown).mockResolvedValueOnce({ id: "m1" }); // eslint-disable-line @typescript-eslint/no-explicit-any

    await act(async () => {
      fireEvent.click(saveBtn);
    });

    const success = await screen.findByText(/Measurements saved/i);
    expect(success).toBeDefined();
  });

  it("clears dashboard state when session is lost", async () => {
    const { rerender } = render(<Home />);

    // Authenticated state (already set in beforeEach)
    expect(screen.getByTestId("navbar")).toBeDefined();

    // Session loss
    (useSession as unknown).mockReturnValue({
      data: null,
      status: "unauthenticated",
    }); // eslint-disable-line @typescript-eslint/no-explicit-any

    act(() => {
      rerender(<Home />);
    });

    // It should effectively re-render or handle the cleanup effect.
    // We check if it still works or doesn't crash.
    await waitFor(() => {
      expect(screen.getByTestId("navbar")).toBeDefined();
    });
  });
});

"use client";

import React, { useEffect, useRef, useState } from "react";
import { Activity, ArrowUp } from "lucide-react";
import { motion, AnimatePresence } from "framer-motion";
import { getClientErrorMessage, requestJson } from "@/lib/client-api";
import type {
  ChatAttachment,
  ChatAttachmentPayload,
  InlineNotice,
} from "@/lib/types";
import { extractAndCleanLogData } from "@/lib/chat-utils";

import { MessageBubble, type Message } from "./Chat/MessageBubble";
import { QuickChips } from "./Chat/QuickChips";
import { ChatInput } from "./Chat/ChatInput";

interface ChatProps {
  readonly onLogParsed: () => void;
  readonly isNewUser?: boolean;
  readonly initialMessage?: string | null;
  readonly onMessageSent?: () => void;
  readonly nudgeStatus?: {
    protein: number;
    proteinTarget: number;
    calories: number;
    calorieTarget: number;
  };
  readonly input: string;
  readonly setInput: (val: string) => void;
}

type ChatResponse = {
  text?: string;
  error?: string;
  warning?: string;
};

export default function Chat({
  onLogParsed,
  isNewUser,
  initialMessage,
  onMessageSent,
  nudgeStatus,
  input,
  setInput,
}: ChatProps) {
  const [messages, setMessages] = useState<Message[]>([
    {
      id: "welcome-msg",
      role: "model",
      text: isNewUser
        ? "Welcome to LiveFit! 👋 I'm your AI assistant. To help you set your targets, could you tell me your age, gender, height, and primary fitness goal?"
        : 'Good morning! 👋 I\'m your LiveFit AI - speak naturally to log anything.\n\n🔍 "Had 3 egg omelette and 150ml milk for breakfast"\n💪 "Finished chest day, 3200kg volume, 8 PRs"\n😴 "Slept 7.5h, bed at 11pm, woke at 6:30"\n⚖️ "Weight 70.5kg this morning"',
      timestamp: "",
    },
  ]);
  const [isTyping, setIsTyping] = useState(false);
  const [pendingAttachments, setPendingAttachments] = useState<
    ChatAttachment[]
  >([]);
  const [notice, setNotice] = useState<InlineNotice | null>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const textInputRef = useRef<HTMLInputElement>(null);
  const [isLoadingHistory, setIsLoadingHistory] = useState(true);
  const isInitialMount = useRef(true);
  const [showScrollBottom, setShowScrollBottom] = useState(false);
  const viewportRef = useRef<HTMLDivElement>(null);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const { scrollTop, scrollHeight, clientHeight } = e.currentTarget;
    const isAtBottom = scrollHeight - scrollTop - clientHeight < 100;
    setShowScrollBottom(!isAtBottom);
  };

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(() => {
    // Proactive Nudge logic
    if (
      nudgeStatus &&
      messages.length === 1 &&
      messages[0].id === "welcome-msg"
    ) {
      const alreadyHasNudge = messages.some((m) => m.id === "protein-nudge");
      if (alreadyHasNudge) return;

      const proteinPct =
        (nudgeStatus.protein / nudgeStatus.proteinTarget) * 100;
      if (proteinPct < 50) {
        setMessages((prev) => {
          if (prev.some((m) => m.id === "protein-nudge")) return prev;
          return [
            ...prev,
            {
              id: "protein-nudge",
              role: "model",
              text: `I noticed you're a bit behind on your protein goal today (${Math.round(nudgeStatus.protein)}g / ${nudgeStatus.proteinTarget}g). Would you like some high-protein dinner ideas to help you catch up? 🥩`,
              timestamp: new Date().toLocaleTimeString([], {
                hour: "2-digit",
                minute: "2-digit",
              }),
            },
          ];
        });
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [nudgeStatus, messages.length]);

  useEffect(() => {
    if (initialMessage) {
      setInput(initialMessage);
      onMessageSent?.();
      // We use a small timeout to ensure the input state is updated before sending
      const timeoutId = setTimeout(() => {
        handleSend();
      }, 100);
      return () => clearTimeout(timeoutId);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialMessage]);

  useEffect(() => {
    async function fetchHistory() {
      try {
        const res = await fetch("/api/chat/history");
        if (!res.ok) return;

        const data = (await res.json()) as Message[];
        if (data && data.length > 0) {
          setMessages(data);
        } else {
          setMessages((prev) => updateWelcomeMessageTimestamp(prev));
        }
      } catch (err) {
        console.error("Failed to fetch chat history:", err);
      } finally {
        setIsLoadingHistory(false);
      }
    }

    void fetchHistory();
  }, []);

  useEffect(() => {
    if (isInitialMount.current) {
      isInitialMount.current = false;
      return;
    }

    chatEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, isTyping]);

  const handleSend = async () => {
    const userText = input.trim();
    const attachedFiles = [...pendingAttachments];

    if ((!userText && attachedFiles.length === 0) || isTyping) return;

    const userMsg = createChatMessage(
      "user",
      userText ||
        (attachedFiles.some((a) => a.mediaType.startsWith("audio"))
          ? "Audio message"
          : "Image attached"),
      attachedFiles,
    );
    setMessages((prev) => [...prev, userMsg]);
    setInput("");
    setPendingAttachments([]);
    setIsTyping(true);
    setNotice(null);

    try {
      const history = messages.map((m) => ({
        role: m.role,
        parts: [{ text: m.text }],
      }));

      const now = new Date();
      const clientDate =
        now.getFullYear() +
        "-" +
        String(now.getMonth() + 1).padStart(2, "0") +
        "-" +
        String(now.getDate()).padStart(2, "0");
      const clientTime =
        String(now.getHours()).padStart(2, "0") +
        ":" +
        String(now.getMinutes()).padStart(2, "0");

      const data = await requestJson<ChatResponse>("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          prompt: userText,
          history,
          images: attachedFiles.map(toPayload), // Backend still uses 'images' key for attachments
          clientDate,
          clientTime,
        }),
      });

      processChatResponse(data);
    } catch (error) {
      handleChatError(error);
    } finally {
      setIsTyping(false);
    }
  };

  const processChatResponse = (data: ChatResponse) => {
    if (data.text) {
      const { hasData, cleanText } = extractAndCleanLogData(data.text);

      if (hasData) {
        onLogParsed();
      } else {
        // Safety Fallback: AI sometimes forgets the DATA block but confirms in text.
        const stateKeywords = [
          "training",
          "lite",
          "light",
          "rest",
          "logged",
          "recorded",
          "saved",
        ];
        const lowerText = cleanText.toLowerCase();
        if (stateKeywords.some((kw) => lowerText.includes(kw))) {
          onLogParsed();
        }
      }

      const modelMsg = createChatMessage("model", cleanText);
      setMessages((prev) => [...prev, modelMsg]);
    }

    if (data.warning) {
      setNotice({ tone: "warning", message: data.warning });
    }
  };

  const handleChatError = (error: unknown) => {
    const message = getClientErrorMessage(error);
    console.error("Chat connection error:", message);
    setNotice({ tone: "error", message });

    const errorMsg = createChatMessage(
      "model",
      `Unable to connect to AI service. ${message}`,
    );
    setMessages((prev) => [...prev, errorMsg]);
  };

  const handleFileSelection = async (
    event: React.ChangeEvent<HTMLInputElement>,
  ) => {
    const files = Array.from(event.target.files ?? []);
    if (files.length === 0) {
      return;
    }

    try {
      const newAttachments = await Promise.all(files.map(readAttachmentFile));
      setPendingAttachments((current) => [...current, ...newAttachments]);
      setNotice(null);
    } catch (error) {
      const message = getClientErrorMessage(error);
      console.error("Failed to read attachment:", message);
      setNotice({
        tone: "error",
        message: `Unable to read selected file: ${message}`,
      });
    } finally {
      event.target.value = "";
    }
  };

  const handleAudioRecorded = async (file: File) => {
    try {
      const audioAttachment = await readAttachmentFile(file);
      setPendingAttachments((current) => [...current, audioAttachment]);
      setNotice(null);
    } catch (error) {
      const message = getClientErrorMessage(error);
      console.error("Failed to read recorded audio:", message);
      setNotice({
        tone: "error",
        message: `Unable to process audio recording: ${message}`,
      });
    }
  };

  const removePendingAttachment = (attachmentId: string) => {
    setPendingAttachments((current) =>
      current.filter((att) => att.id !== attachmentId),
    );
  };

  const handleQuickChipSelect = (text: string) => {
    setInput(text);
    textInputRef.current?.focus();
  };

  return (
    <div
      className="flex-1 min-w-0 h-full bg-[var(--surface)] rounded-[var(--radius-xl)] flex flex-col border border-[var(--border)] shadow-[var(--shadow-lg)] overflow-hidden transition-all duration-300 [background-clip:padding-box] [transform:translateZ(0)] [mask-image:linear-gradient(#fff,#fff)] relative"
      role="log"
      aria-label="Chat history"
      aria-live="polite"
    >
      <div
        ref={viewportRef}
        onScroll={handleScroll}
        className="flex-1 overflow-y-auto overflow-x-hidden flex flex-col scroll-smooth h-full no-scrollbar chat-viewport rounded-[inherit]"
      >
        <div className="w-full flex flex-col chat-content-v-inset">
          {isLoadingHistory ? (
            <div className="flex justify-center py-6" data-testid="chat-loader">
              <Activity
                className="w-6 h-6 animate-pulse"
                style={{ color: "#e67e22" }}
                strokeWidth={2.5}
              />
            </div>
          ) : (
            <AnimatePresence mode="popLayout">
              {messages.map((msg, index) => {
                const isFirstInGroup =
                  index === 0 || messages[index - 1].role !== msg.role;
                return (
                  <MessageBubble
                    key={msg.id}
                    msg={msg}
                    isFirstInGroup={isFirstInGroup}
                    isNewUser={isNewUser}
                  />
                );
              })}
            </AnimatePresence>
          )}

          {isTyping && (
            <motion.div
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              className="chat-msg-row mt-4"
            >
              <div className="chat-avatar bg-[var(--accent)] text-[var(--accent-inv)]">
                <Activity
                  className="w-4.5 h-4.5 text-[var(--accent-inv)] animate-pulse"
                  strokeWidth={3}
                />
              </div>
              <div className="chat-msg-bubble chat-bubble-model flex gap-2 items-center">
                <div className="w-1.5 h-1.5 rounded-full bg-[var(--accent)]/40 animate-bounce [animation-duration:1s]" />
                <div className="w-1.5 h-1.5 rounded-full bg-[var(--accent)]/40 animate-bounce [animation-duration:1s] [animation-delay:0.2s]" />
                <div className="w-1.5 h-1.5 rounded-full bg-[var(--accent)]/40 animate-bounce [animation-duration:1s] [animation-delay:0.4s]" />
              </div>
            </motion.div>
          )}
        </div>
        <div ref={chatEndRef} />
      </div>

      <AnimatePresence>
        {showScrollBottom && (
          <motion.button
            initial={{ opacity: 0, scale: 0.8, y: 10 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.8, y: 10 }}
            onClick={scrollToBottom}
            className="absolute bottom-40 right-8 z-50 w-10 h-10 rounded-full bg-[var(--accent)] text-[var(--accent-inv)] shadow-lg flex items-center justify-center hover:scale-110 active:scale-95 transition-transform"
            aria-label="Scroll to bottom"
          >
            <ArrowUp className="w-5 h-5 rotate-180" strokeWidth={3} />
          </motion.button>
        )}
      </AnimatePresence>

      <div className="chat-footer-container">
        <AnimatePresence>
          {notice && (
            <motion.div
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: "auto" }}
              exit={{ opacity: 0, height: 0 }}
              className="overflow-hidden"
            >
              <div
                className={`notice-banner notice-banner-${notice.tone} chat-notice`}
                role="status"
                aria-live="polite"
              >
                {notice.message}
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        <QuickChips onSelect={handleQuickChipSelect} />

        <ChatInput
          input={input}
          setInput={setInput}
          isTyping={isTyping}
          pendingAttachments={pendingAttachments}
          onSend={handleSend}
          onFileSelect={handleFileSelection}
          onRemoveAttachment={removePendingAttachment}
          textInputRef={textInputRef}
        />
      </div>
    </div>
  );
}

function updateWelcomeMessageTimestamp(prev: Message[]): Message[] {
  return prev.map((msg) =>
    msg.id === "welcome-msg" && msg.timestamp === ""
      ? {
          ...msg,
          timestamp: new Date().toLocaleTimeString([], {
            hour: "2-digit",
            minute: "2-digit",
          }),
        }
      : msg,
  );
}

function createChatMessage(
  role: "user" | "model",
  text: string,
  attachments?: ChatAttachment[],
): Message {
  return {
    id: crypto.randomUUID(),
    role,
    text,
    timestamp: new Date().toLocaleTimeString([], {
      hour: "2-digit",
      minute: "2-digit",
    }),
    attachments,
  };
}

function toPayload(attachment: ChatAttachment): ChatAttachmentPayload {
  return {
    base64: attachment.base64,
    mediaType: attachment.mediaType,
    name: attachment.name,
  };
}

async function readAttachmentFile(file: File): Promise<ChatAttachment> {
  const previewUrl = await readFileAsDataUrl(file);
  const [prefix, base64 = ""] = previewUrl.split(",");
  const mediaType =
    file.type || getMediaTypeFromDataUrl(prefix) || "application/octet-stream";

  return {
    id: crypto.randomUUID(),
    base64,
    mediaType,
    previewUrl,
    name: file.name,
  };
}

function readFileAsDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      if (typeof reader.result === "string") {
        resolve(reader.result);
        return;
      }

      reject(new Error("Unexpected file reader result."));
    };
    reader.onerror = () =>
      reject(reader.error ?? new Error("Failed to read file."));
    reader.readAsDataURL(file);
  });
}

function getMediaTypeFromDataUrl(prefix: string): string | null {
  const match = /^data:(.*?);base64$/i.exec(prefix);
  return match?.[1] ?? null;
}

