      id: '2',
      role: 'model' as const,
      text: 'Here is your response',
      timestamp: '10:01 AM',
    };
    render(<MessageBubble msg={msg} isFirstInGroup={true} />);
    expect(screen.getByText('Here is your response')).toBeDefined();
  });

  it('renders attachments', () => {
