      expect(screen.getByText('Measurement History')).toBeDefined();
      expect(screen.getByText('1 records')).toBeDefined();
    });
    // Check table content
    expect(screen.getAllByText('75').length).toBeGreaterThan(1); // One in stats, one in table
  });

  it('renders empty message when no latest measurement', async () => {
    await act(async () => {
      render(<BodyTab {...defaultProps} latestMeasurement={null} />);
    });
    expect(screen.getByText('No data recorded')).toBeDefined();
  });

  it('renders all measurement fields in the input grid', async () => {
    await act(async () => {
      render(<BodyTab {...defaultProps} />);
    });
    expect(screen.getAllByText(/weight/i).length).toBeGreaterThan(0);
    expect(screen.getAllByText(/waist/i).length).toBeGreaterThan(0);
    expect(screen.getAllByText(/chest/i).length).toBeGreaterThan(0);
    expect(screen.getAllByText(/arms/i).length).toBeGreaterThan(0);
    expect(screen.getAllByText(/thighs/i).length).toBeGreaterThan(0);
    expect(screen.getAllByText(/hips/i).length).toBeGreaterThan(0);
    expect(screen.getAllByText(/calves/i).length).toBeGreaterThan(0);
    expect(screen.getAllByText(/neck/i).length).toBeGreaterThan(0);
    expect(screen.getAllByText(/body fat/i).length).toBeGreaterThan(0);
  });

  it('renders latest measurement values in the stats card', async () => {
    await act(async () => {
      render(<BodyTab {...defaultProps} />);
    });
    await waitFor(() => {
      expect(screen.getAllByText('75').length).toBeGreaterThan(0);
      expect(screen.getAllByText('85').length).toBeGreaterThan(0);
      expect(screen.getAllByText('15').length).toBeGreaterThan(0); // Body Fat
    });
  });

  it('handles fetch error gracefully', async () => {
    const consoleSpy = vi.spyOn(console, 'error').mockImplementation(() => {});
    mockFetch.mockRejectedValueOnce(new Error('Fetch failed'));
    await act(async () => {
      render(<BodyTab {...defaultProps} />);
    });
    // Should still render but without history records
    await waitFor(() => {
      expect(screen.queryByText('1 records')).toBeNull();
    });
    consoleSpy.mockRestore();
  });
});

import { render, screen, cleanup, fireEvent, act } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import LogTab from './LogTab';

// Mock framer-motion
vi.mock('framer-motion', () => ({
  motion: {
    div: ({ children, whileHover, whileTap, initial, animate, variants, custom, ...props }: unknown) => <div {...props}>{children}</div>,
  },
  AnimatePresence: ({ children }: { children: React.ReactNode }) => <>{children}</>,
}));

describe('LogTab Component', () => {
  const defaultProps = {
    foodLog: [
      { id: 'f1', name: 'Chicken Breast', protein: 30, kcal: 165, carbs: 0, fats: 3, fiber: 0, time: new Date('2026-03-18T12:00:00Z'), userId: 'u1' },
      { id: 'f2', name: 'Rice', protein: 5, kcal: 200, carbs: 45, fats: 1, fiber: 2, time: new Date('2026-03-18T12:30:00Z'), userId: 'u1' },
    ],
    protein: 35,
    workouts: [
      {
        id: 'w1',
        focus: 'Push Day',
        volume: 5000,
        time: new Date('2026-03-18T10:00:00Z'),
        userId: 'u1',
        details: null,
        routineId: null,
        exercises: [
          {
            id: 'we1',
            workoutLogId: 'w1',
            exerciseId: 'e1',
            customName: null,
            order: 0,
            exercise: { id: 'e1', name: 'Bench Press', category: 'Chest', equipment: 'Barbell' },
            sets: [
              { id: 's1', workoutExerciseId: 'we1', setNumber: 1, reps: 10, weight: 60, distance: null, duration: null, isWarmup: false, isDrop: false, isFailure: false },
            ],
          },
        ],
      },
    ],
    sleepLogs: [
      { id: 's1', hours: 8, time: new Date('2026-03-18T07:00:00Z'), userId: 'u1', bedTime: '23:00', wakeTime: '07:00', quality: null },
    ],
  };

  beforeEach(() => {
    vi.clearAllMocks();
  });

  afterEach(() => {
    cleanup();
  });

  it('renders food log items correctly', async () => {
    await act(async () => {
      render(<LogTab {...defaultProps} />);
    });
    expect(screen.getByText('Chicken Breast')).toBeDefined();
    expect(screen.getByText('Rice')).toBeDefined();
    expect(screen.getByText('35g')).toBeDefined(); // Total protein display
    expect(screen.getByText('30g')).toBeDefined(); // Individual protein
  });

  it('renders workout logs correctly', async () => {
    await act(async () => {
      render(<LogTab {...defaultProps} />);
    });
    expect(screen.getByText('Push Day')).toBeDefined();
    expect(screen.getByText('5000 kg')).toBeDefined();
  });

  it('renders sleep logs correctly', async () => {
    await act(async () => {
      render(<LogTab {...defaultProps} />);
    });
    expect(screen.getByText('8')).toBeDefined();
    expect(screen.getByText('hrs')).toBeDefined();
    expect(screen.getByText(/23:00 to 07:00/)).toBeDefined();
  });

  it('renders empty messages when logs are missing', async () => {
    await act(async () => {
      render(<LogTab foodLog={[]} protein={0} workouts={[]} sleepLogs={[]} />);
    });
    expect(screen.getByText(/No food logged yet/i)).toBeDefined();
    expect(screen.getByText(/No sleep logged yet/i)).toBeDefined();
  });

  it('toggles workout details when clicked', async () => {
    await act(async () => {
      render(<LogTab {...defaultProps} />);
    });
    const workoutBtn = screen.getByText('Push Day').closest('button')!;
    
    // Initially details are hidden
    expect(screen.queryByText('Bench Press')).toBeNull();
    
    // Click to expand
    fireEvent.click(workoutBtn);
    expect(screen.getByText('Bench Press')).toBeDefined();
    expect(screen.getByText('1 Sets')).toBeDefined();
    
    // Click to collapse
    fireEvent.click(workoutBtn);
    expect(screen.queryByText('Bench Press')).toBeNull();
  });

  it('renders all nutritional info for food items', async () => {
    await act(async () => {
      render(<LogTab {...defaultProps} />);
    });
    expect(screen.getByText('165 kcal')).toBeDefined();
    expect(screen.getAllByText('0g').length).toBeGreaterThan(0);
    expect(screen.getByText('3g')).toBeDefined();
  });
});
